`include "common.svh"
`timescale 1ns/1ps

// Functional, self-checking testbench for the L_PJG detector.
//
// It loads the input stimulus (H / y / N0) that was generated by the MIMO
// platform (L_PJG_qtz, Tx=32/Rx=128, parallel=8, 16 sweeps) together with the
// golden output x_p8.txt, drives the DUT through a full detection, captures
// the resulting x_o at x_valid_o and compares it bit-exact against the golden.
//
// IMPORTANT: the golden x_p8.txt corresponds to iter=16 sweeps, therefore this
// testbench must be compiled with TEST_ITER_NUM=16 (iter_num_i = 15 -> 16
// sweeps). With any other TEST_ITER_NUM the check is expected to FAIL.
//
// Usage (EDA server, from L_PJG/sim):
//   make com-fc        # compile  (output dir: vcs_top_fc_iter16)
//   make sim-fc        # compile + run (prints FC: PASS / FC: FAIL)
// (see makefile targets "com-fc"/"sim-fc"; they compile sim_rtl_fc.f with top
//  tb_fc_detector and TEST_ITER_NUM=16)

`ifndef FC_DATA_DIR
`define FC_DATA_DIR "/home/asic03/graduate/proj_hujinjie/L_PJG/rtl/data/128x32_c5"
`endif

module tb_fc_detector;

    // Parameters
    localparam RX = 128;
    localparam ITER_NUM = `TEST_ITER_NUM-1;
    localparam INPUT_CC = RX / SYSTOLIC_PARALLEL;
    localparam real CLK_PERIOD = 1.4; // Clock period in time units

    // Stimulus / golden directory (compile-time override via -DFC_DATA_DIR="...")
    string data_dir = `FC_DATA_DIR;

    // Clock and reset signals
    reg clk;
    reg rst_n;

    // Input stimulus memory (loaded from the data directory)
    int signed count, count_new;
    reg signed [32-1:0] H_in_real_data[RX*TX-1:0];
    reg signed [32-1:0] H_in_img_data [RX*TX-1:0];
    reg signed [32-1:0] y_in_real_data[RX-1:0];
    reg signed [32-1:0] y_in_img_data[RX-1:0] ;
    reg signed [32-1:0] noise_data[0:0];

    // Golden output (x_p8.txt: 32 complex symbols packed as
    // {real[10:0], imag[10:0]}, i.e. X_QTZ.width = 22 bits per entry)
    reg [32-1:0] x_golden[TX-1:0];

    reg signed [SYSTOLIC_PARALLEL-1:0][TX-1:0][H_QTZ.width/2-1:0] H_in_real;
    reg signed [SYSTOLIC_PARALLEL-1:0][TX-1:0][H_QTZ.width/2-1:0] H_in_img ;
    reg signed [SYSTOLIC_PARALLEL-1:0][Y_QTZ.width/2-1:0] y_in_real;
    reg signed [SYSTOLIC_PARALLEL-1:0][Y_QTZ.width/2-1:0] y_in_img ;

    // 输入信号
    reg [SYSTOLIC_PARALLEL-1:0][TX-1:0][H_QTZ.width-1:0] H_in;
    reg [SYSTOLIC_PARALLEL-1:0][Y_QTZ.width-1:0] y_in;
    reg [N0_QTZ.width-1:0] n0_in;
    reg finish_flag_i;
    wire [ITER_NUM_WIDTH-1:0] iter_num;

    // 输出信号
    wire [TX-1:0][X_QTZ.width-1:0] x_o;
    wire x_valid_o;

    // 例化被测模块 (DUT)
    logic systolic_rx_valid;
    logic systolic_rx_ready;

    detector u_detector (
        .clk(clk),
        .rst_n(rst_n),
        .H_in(H_in),
        .y_in(y_in),
        .n0_in(n0_in),
        .finish_flag_i(finish_flag_i),
        .x_o(x_o),
        .x_valid_o(x_valid_o),
        .iter_num_i(iter_num),
        .*
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #(CLK_PERIOD / 2) clk = ~clk;
    end

    // Reset generation
    initial begin
        rst_n = 0;
        #(CLK_PERIOD * 2.5);
        rst_n = 1;
    end

    // Test sequence: load stimulus + golden, then wait for the result
    initial begin
        int i;
        integer mismatches;
        logic timed_out;
        int cyc;

        // Initialize inputs & golden
        $readmemh({data_dir, "/H_r.txt"}, H_in_real_data);
        $readmemh({data_dir, "/H_i.txt"}, H_in_img_data);
        $readmemh({data_dir, "/y_r.txt"}, y_in_real_data);
        $readmemh({data_dir, "/y_i.txt"}, y_in_img_data);
        $readmemh({data_dir, "/noise.txt"}, noise_data);
        $readmemh({data_dir, "/x_p8.txt"}, x_golden);

        $display("FC: iter_num_i = %0d (=> %0d sweeps), TEST_ITER_NUM = `TEST_ITER_NUM", ITER_NUM, ITER_NUM+1);
        $display("FC: stimulus dir = %s", data_dir);

        // Wait for reset to complete
        @(posedge rst_n);
        @(posedge clk);

        // Poll for the DUT result (x_valid_o). Watchdog to avoid hanging.
        timed_out = 1'b1;
        cyc = 0;
        while (cyc < 500000) begin
            @(posedge clk);
            cyc = cyc + 1;
            if (x_valid_o) begin
                timed_out = 1'b0;
                break;
            end
        end

        if (timed_out) begin
            $display("FC: TIMEOUT - x_valid_o never asserted after %0d cycles", cyc);
            $display("FC: FAIL (timeout)");
            $finish;
        end

        // Compare x_o against golden x_p8 (bit-exact, 22-bit complex entry)
        mismatches = 0;
        for (i = 0; i < TX; i = i + 1) begin
            if (x_o[i] !== x_golden[i][0 +: X_QTZ.width]) begin
                if (mismatches < 10)
                    $display("FC: mismatch @ tx[%0d] got=%h exp=%h", i, x_o[i], x_golden[i][0 +: X_QTZ.width]);
                mismatches = mismatches + 1;
            end
        end

`ifdef FC_DUMP_XO
        // Optional full dump of got/exp for offline precision analysis
        // (compile with -DFC_DUMP_XO -DFC_DUMP_FILE="<path>")
        begin
            integer fd;
            fd = $fopen(`FC_DUMP_FILE, "w");
            for (i = 0; i < TX; i = i + 1) begin
                $fdisplay(fd, "tx[%0d] got=%h exp=%h", i, x_o[i],
                          x_golden[i][0 +: X_QTZ.width]);
            end
            $fclose(fd);
        end
`endif

        if (mismatches == 0) begin
            $display("FC: PASS - x_o matches golden x_p8 for all %0d TX entries (iter=16 sweeps)", TX);
        end else begin
            $display("FC: FAIL - %0d/%0d TX entries mismatch", mismatches, TX);
        end

        $finish;
    end

    assign n0_in = noise_data[0][0+:$bits(n0_in)];
    generate
        for (genvar i = 0; i < SYSTOLIC_PARALLEL; i++) begin
            assign y_in[i] = {y_in_real[i], y_in_img[i]};
            for (genvar j = 0; j < TX; j++) begin
                assign H_in[i][j] = {H_in_real[i][j], H_in_img[i][j]};
            end
        end
    endgenerate

    assign count_new = (count == INPUT_CC-1) ? 'b0 : count + 1'b1;
    assign finish_flag_i = count == INPUT_CC - 1;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 'b0;
            systolic_rx_valid <= 1'b1;
        end else if (systolic_rx_valid & systolic_rx_ready) begin
            count <= count_new;
            systolic_rx_valid <= 1'b1;
        end
    end

    generate
        for (genvar i = 0; i < SYSTOLIC_PARALLEL; i++) begin
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    y_in_real[i] <= y_in_real_data[i];
                    y_in_img [i] <= y_in_img_data [i] ;
                end else if (systolic_rx_ready & systolic_rx_valid) begin
                    y_in_real[i] <= y_in_real_data[count_new*SYSTOLIC_PARALLEL + i];
                    y_in_img [i] <= y_in_img_data [count_new*SYSTOLIC_PARALLEL + i];
                end
            end

            for (genvar j = 0; j < TX; j++) begin
                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        H_in_real[i][j] <= H_in_real_data[i*TX + j][0 +: H_QTZ.width/2];
                        H_in_img [i][j] <= H_in_img_data [i*TX + j][0 +: H_QTZ.width/2];
                    end else if (systolic_rx_valid & systolic_rx_ready) begin
                        H_in_real[i][j] <= H_in_real_data[count_new*(TX*SYSTOLIC_PARALLEL) + i*TX + j ][0 +: H_QTZ.width/2];
                        H_in_img [i][j] <= H_in_img_data [count_new*(TX*SYSTOLIC_PARALLEL) + i*TX + j ][0 +: H_QTZ.width/2];
                    end
                end
            end
        end
    endgenerate

    assign iter_num = ITER_NUM;

endmodule
